CREATE TABLE security_rate_buckets (
    bucket_key VARCHAR(64) PRIMARY KEY,
    hits INTEGER NOT NULL,
    expires_at TIMESTAMP NOT NULL
);
CREATE INDEX idx_security_rate_expiry ON security_rate_buckets(expires_at);
-- Requests, not bearer tokens: links are generated by the delivery worker.
CREATE TABLE security_mail_requests (
    id UUID PRIMARY KEY,
    action VARCHAR(24) NOT NULL,
    address VARCHAR(254) NOT NULL,
    attempts INTEGER NOT NULL DEFAULT 0,
    status VARCHAR(16) NOT NULL DEFAULT 'PENDING',
    available_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_security_mail_pending ON security_mail_requests(status, available_at);
